mapper.select:
select T.id
from tasks T

    inner join task_categories TC on T.id = TC.task_id
    inner join categories C on TC.category_id = C.id and C.name = #{category}

where T.user_id = #{userId}

    and T.status = #{status}


    and T.priority = #{priority}


    and T.due_date < #{dueBefore}

order by T.created_at desc
limit #{page.limit} OFFSET #{page.offset}

select count(T.id)
from tasks T

    inner join task_categories TC on T.id = TC.task_id
    inner join categories C on TC.category_id = C.id and C.name = #{category}

where T.user_id = #{userId}

    and T.status = #{status}


    and T.priority = #{priority}


    and T.due_date < #{dueBefore}

select T.id
from tasks T
where T.user_id = #{userId}
and T.due_date >= #{start}
and T.due_date < #{end}
and T.status != 'COMPLETED'
and T.status != 'CANCELLED'
order by T.due_date asc
